using System;
using System.Collections.Generic;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Myrtana.Ui.Skin
{
    /// <summary>
    /// Everything the G3 skin needs from the original GUI data, as plain data: the widget theme, the index of packed
    /// images and the 62 screen layouts. Generated by the editor importer (menu <c>G3/GUI/Import</c>) from
    /// <c>gui.pak</c> + <c>g3.igl</c> into <c>Assets/G3Imported/Gui/Resources/G3Gui/G3GuiData.json</c> (game-derived,
    /// git-ignored). Coordinates are 1024×768 reference pixels. See Docs/ui-skin.md.
    /// </summary>
    public sealed class GuiSkinData
    {
        public const int CurrentFormat = 1;

        public int Format { get; set; } = CurrentFormat;
        /// <summary>Where it came from (informational), e.g. "gui.pak + Library.pak/g3.igl".</summary>
        public string Source { get; set; }
        public ThemeData Theme { get; set; } = new ThemeData();
        public List<ImageData> Images { get; set; } = new List<ImageData>();
        /// <summary>Top-level dialogs of g3.gui.res (pages, views, menus), keyed by <see cref="WindowData.ResName"/>.</summary>
        public List<WindowData> Screens { get; set; } = new List<WindowData>();
    }

    public sealed class ThemeData
    {
        public string Name { get; set; }
        /// <summary>The 58 GUI.dll metrics by name ("Border.Control.X" = 3, "VScroll.Track.X" = 17 …).</summary>
        public Dictionary<string, int> Metrics { get; set; } = new Dictionary<string, int>();
        public List<ThemeElementData> Elements { get; set; } = new List<ThemeElementData>();
        public List<ThemeCursorData> Cursors { get; set; } = new List<ThemeCursorData>();

        public int Metric(string name, int fallback = 0) => Metrics != null && Metrics.TryGetValue(name, out int v) ? v : fallback;
    }

    /// <summary>One theme element (a widget layer such as "listctrl_item_tiles_back") with its colours per state.</summary>
    public sealed class ThemeElementData
    {
        /// <summary>Element key, e.g. "listctrl_item_details_back".</summary>
        public string Name { get; set; }
        /// <summary>Image key of the cropped bitmap (asset "Theme/&lt;Name&gt;.png").</summary>
        public string Image { get; set; }
        public int Width { get; set; }
        public int Height { get; set; }
        /// <summary>Theme text format (26; 27 for push buttons = centred).</summary>
        public int TextFormat { get; set; }
        /// <summary>Theme draw mode (0 borders/frames, 4 bars and list items, 5 icons and most widgets, 36/37 menu bars).</summary>
        public int DrawMode { get; set; }
        /// <summary>9-slice border in source pixels (left, top, right, bottom) for frame images; null = stretched.</summary>
        public int[] Slice { get; set; }
        /// <summary>Six entries in <see cref="WidgetState"/> order.</summary>
        public List<StateColors> States { get; set; } = new List<StateColors>();

        public SkinColor Text(WidgetState s) => SkinColor.Parse(States[(int)s].Text);
        public SkinColor Blend(WidgetState s) => SkinColor.Parse(States[(int)s].Blend);
    }

    public sealed class StateColors
    {
        public string Text { get; set; }
        public string Blend { get; set; }
    }

    public sealed class ThemeCursorData
    {
        public string Name { get; set; }
        public string Image { get; set; }
        public string Color { get; set; }
        public int HotSpotX { get; set; }
        public int HotSpotY { get; set; }
    }

    /// <summary>One packed image of g3.igl (item icon, HUD icon, view background, map, slide).</summary>
    public sealed class ImageData
    {
        /// <summary>File name as used by layouts and item templates, e.g. "IT_Apple.tga" (lookups ignore case and extension).</summary>
        public string Name { get; set; }
        /// <summary>igl group: it_alchemy … it_weapons, hud_icons, hud_backgrounds, hud_maps, hud_slides.</summary>
        public string Group { get; set; }
        public int Width { get; set; }
        public int Height { get; set; }
    }

    /// <summary>A window of a g3.gui.res layout (a screen, or a control inside it).</summary>
    public sealed class WindowData
    {
        /// <summary>GUI.Window.Class: View, Static, Button, Slider, ListCtrl, RadioButton, TabCtrl, ProgressBar, AnimateCtrl, CheckBox.</summary>
        public string Class { get; set; }
        /// <summary>Game.dll class for screens (gCHUDViewDialog2 …).</summary>
        public string GfcClass { get; set; }
        /// <summary>IDD_… for screens, IDC_… for controls (the name presenters query, e.g. "IDC_LISTCTRL_DIALOG_2").</summary>
        public string ResName { get; set; }
        /// <summary>Design-time text (German placeholder); the game replaces it from the string table.</summary>
        public string Text { get; set; }
        /// <summary>left, top, right, bottom in 1024×768 reference pixels, relative to the parent.</summary>
        public int[] Rect { get; set; }
        /// <summary>GUI.Window.Anchor flags (<see cref="AnchorFlags"/>).</summary>
        public int Anchor { get; set; }
        public uint Style { get; set; }
        public FontData Font { get; set; }
        /// <summary>Background (View) or picture (Static) image name, resolved through the image index ("G3_HUD_View_Dialog_Back.tga").</summary>
        public string Image { get; set; }
        /// <summary>Explicit GUI.Static.TextColor (rare).</summary>
        public string TextColor { get; set; }
        /// <summary>Remaining class-specific attributes without the "GUI." prefix (ListCtrl.Tile.Size, TabCtrl.ItemSize, ProgressBar.Color.Bar …).</summary>
        public Dictionary<string, string> Attributes { get; set; }
        /// <summary>Tab control items (Index, Image, Text).</summary>
        public List<Dictionary<string, string>> Items { get; set; }
        public List<WindowData> Children { get; set; }

        [JsonIgnore] public int Left => Rect[0];
        [JsonIgnore] public int Top => Rect[1];
        [JsonIgnore] public int Width => Rect[2] - Rect[0];
        [JsonIgnore] public int Height => Rect[3] - Rect[1];

        public string Attribute(string key) => Attributes != null && Attributes.TryGetValue(key, out var v) ? v : null;

        public IEnumerable<WindowData> Descendants()
        {
            if (Children == null) yield break;
            foreach (var c in Children)
            {
                yield return c;
                foreach (var d in c.Descendants()) yield return d;
            }
        }

        public WindowData Find(string resName)
        {
            foreach (var d in Descendants())
                if (string.Equals(d.ResName, resName, StringComparison.OrdinalIgnoreCase)) return d;
            return null;
        }

        public override string ToString() => $"{Class} {ResName} {Left},{Top} {Width}x{Height}";
    }

    /// <summary>Font of a layout window. The face in the res file is always the design-time "Times New Roman"; the skin
    /// draws every text with Gothic3.ttf (Docs/formats-gui.md §5), so only size and style matter.</summary>
    public sealed class FontData
    {
        /// <summary>Pixel height on the 768-line reference screen.</summary>
        public int Size { get; set; }
        public bool Bold { get; set; }
        public bool Italic { get; set; }
    }

    /// <summary>Reads and writes <see cref="GuiSkinData"/> (System.Text.Json, camelCase, readable Cyrillic).</summary>
    public static class GuiSkinJson
    {
        static readonly JsonSerializerOptions Options = new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
            DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
            Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
            WriteIndented = false,
        };

        public static string Write(GuiSkinData data) => JsonSerializer.Serialize(data, Options);

        public static GuiSkinData Read(string json)
        {
            var data = JsonSerializer.Deserialize<GuiSkinData>(json, Options) ?? throw new FormatException("empty G3 skin data");
            if (data.Format != GuiSkinData.CurrentFormat)
                throw new FormatException($"G3 skin data format {data.Format}, expected {GuiSkinData.CurrentFormat}: re-run G3/GUI/Import");
            return data;
        }
    }
}
